+import { Terminal, Copy, Check, ChevronDown, Sparkles, Rocket, Settings, Plug } from 'lucide-react';
+import { cn } from '@/lib/utils';
+
+interface StepProps {
+  number: number;
+  title: string;
+  description: string;
+  command?: string;
+  icon: React.ReactNode;
+  isLast?: boolean;
+  delay: number;
+}
+
+function CopyButton({ text }: { text: string }) {
+  const [copied, setCopied] = useState(false);
+
+  const handleCopy = async () => {
+    await navigator.clipboard.writeText(text);
+    setCopied(true);
+    setTimeout(() => setCopied(false), 2000);
+  };
+
+  return (
+    <motion.button
+      onClick={handleCopy}
+      className={cn(
+        'absolute right-3 top-1/2 -translate-y-1/2',
+        'rounded-lg p-2 transition-all duration-200',
+        'opacity-0 group-hover:opacity-100',
+        'bg-white/5 hover:bg-white/10',
+        'border border-white/10 hover:border-orange-500/30',
+        'focus:outline-none focus:ring-2 focus:ring-orange-500/50'
+      )}
+      whileHover={{ scale: 1.05 }}
+      whileTap={{ scale: 0.95 }}
+      aria-label={copied ? 'Copied!' : 'Copy to clipboard'}
+    >
+      <AnimatePresence mode="wait">
+        {copied ? (
+          <motion.div
+            key="check"
+            initial={{ scale: 0, rotate: -180 }}
+            animate={{ scale: 1, rotate: 0 }}
+            exit={{ scale: 0, rotate: 180 }}
+            transition={{ type: 'spring', stiffness: 500, damping: 30 }}
+          >
+            <Check className="h-4 w-4 text-emerald-400" />
+          </motion.div>
+        ) : (
+          <motion.div key="copy" initial={{ scale: 0 }} animate={{ scale: 1 }} exit={{ scale: 0 }}>
+            <Copy className="h-4 w-4 text-white/60" />
+          </motion.div>
+        )}
+      </AnimatePresence>
+    </motion.button>
+  );
+}
+
+function InstallStep({ number, title, description, command, icon, isLast, delay }: StepProps) {
+  return (
+    <motion.div
+      className="relative flex gap-4"
+      initial={{ opacity: 0, x: -20 }}
+      animate={{ opacity: 1, x: 0 }}
+      transition={{ delay, duration: 0.4, ease: [0.25, 0.46, 0.45, 0.94] }}
+    >
+      {/* Timeline connector */}
+      <div className="flex flex-col items-center">
+        {/* Step number bubble */}
+        <motion.div
+          className={cn(
+            'relative flex h-10 w-10 items-center justify-center rounded-xl',
+            'bg-gradient-to-br from-orange-500/20 to-amber-500/10',
+            'border border-orange-500/30',
+            'shadow-[0_0_20px_rgba(249,115,22,0.15)]'
+          )}
+          initial={{ scale: 0 }}
+          animate={{ scale: 1 }}
+          transition={{ delay: delay + 0.1, type: 'spring', stiffness: 400 }}
+        >
